<?php $money=static fn(int$v):string=>($v<0?'- ':'').'R$ '.number_format(abs($v)/100,2,',','.');$date=static fn(?string$v,bool$t=false):string=>$v?date($t?'d/m/Y H:i':'d/m/Y',strtotime($v)):'-';$labels=['EM_ABERTO'=>'Em aberto','DISPONIVEL'=>'Disponível','PAGA'=>'Paga','ESTORNADA'=>'Estornada','CANCELADA'=>'Cancelada']; ?>
<header class="panel-page-heading"><div><span>Programa de afiliados</span><h1>Comissões</h1><p>Histórico de comissões, pagamentos recebidos e ajustes.</p></div></header>
<section class="metric-grid affiliate-finance-summary" aria-label="Resumo financeiro"><article><span>Em aberto</span><strong><?= e($money((int)$summary['em_aberto_centavos'])) ?></strong><small>Dentro dos 7 dias</small></article><article><span>Saldo disponível</span><strong><?= e($money((int)$summary['saldo_disponivel_centavos'])) ?></strong><small>Após pagamentos e ajustes</small></article><article><span>Total recebido</span><strong><?= e($money((int)$summary['total_pago_centavos'])) ?></strong><small>Pagamentos registrados</small></article></section>
<section class="panel-card affiliate-balance-help"><p><strong>Em aberto:</strong> comissões geradas que ainda estão dentro do período de liberação de 7 dias.</p><p><strong>Saldo disponível:</strong> valor já liberado, considerando pagamentos anteriores e eventuais ajustes.</p></section>
<section class="panel-card admin-filter-card"><form class="affiliate-filter-form" method="get" action="<?= url('/afiliado/comissoes') ?>"><label>Desde<input type="date" name="de" value="<?= e($filters['de']) ?>"></label><label>Até<input type="date" name="ate" value="<?= e($filters['ate']) ?>"></label><label>Status<select name="status"><option value="">Todos</option><?php foreach($labels as$value=>$label):?><option value="<?= e($value) ?>" <?= $filters['status']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach;?></select></label><label>Proprietário<select name="proprietario"><option value="0">Todos</option><?php foreach($owners as$o):?><option value="<?= (int)$o['id'] ?>" <?= (int)$filters['proprietario']===(int)$o['id']?'selected':'' ?>><?= e($o['nome']) ?></option><?php endforeach;?></select></label><label>Chácara<input type="search" name="chacara" value="<?= e($filters['chacara']) ?>"></label><div class="form-actions"><button class="btn btn-primary" type="submit">Filtrar</button><a class="btn btn-outline" href="<?= url('/afiliado/comissoes') ?>">Limpar</a></div></form></section>
<section class="panel-card"><div class="panel-card-heading"><h2>Histórico de comissões</h2></div><?php if(!$result['items']):?><div class="empty-preview"><span aria-hidden="true">&#36;</span><div><strong>Nenhuma comissão registrada</strong><p>As comissões aparecerão após a confirmação das mensalidades.</p></div></div><?php else:?><div class="responsive-table"><table class="panel-table"><thead><tr><th scope="col">Confirmação</th><th scope="col">Liberação</th><th scope="col">Proprietário</th><th scope="col">Chácara</th><th scope="col">Percentual</th><th scope="col">Comissão</th><th scope="col">Status</th></tr></thead><tbody><?php foreach($result['items']as$c):?><tr><td><?= e($date($c['confirmado_em'],true)) ?></td><td><?= e($date($c['disponivel_em'],true)) ?></td><td><?= e($c['proprietario_nome']) ?></td><td><?= e($c['chacara_nome']) ?></td><td><?= e(number_format(((int)$c['percentual_bps'])/100,2,',','.').'%') ?></td><td><strong><?= e($money((int)$c['valor_comissao_centavos'])) ?></strong></td><td><span class="status-pill affiliate-commission-status affiliate-commission-<?= e(strtolower($c['status_exibicao'])) ?>"><?= e($labels[$c['status_exibicao']]??$c['status_exibicao']) ?></span></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php if($result['pages']>1):?><nav class="panel-pagination" aria-label="Paginação"><?php for($p=1;$p<=$result['pages'];$p++):$query=array_merge($filters,['pagina'=>$p]);?><a class="<?= $p===$result['page']?'active':'' ?>" href="<?= url('/afiliado/comissoes?'.http_build_query($query)) ?>"><?= $p ?></a><?php endfor;?></nav><?php endif;?></section>
<section class="affiliate-history-grid"><article class="panel-card"><div class="panel-card-heading"><h2>Pagamentos recebidos</h2></div><?php if(!$payments):?><div class="empty-preview affiliate-empty-compact"><div><strong>Nenhum pagamento recebido</strong><p>Os pagamentos registrados aparecerão aqui.</p></div></div><?php else:?><div class="responsive-table"><table class="panel-table affiliate-compact-table"><thead><tr><th scope="col">Data</th><th scope="col">Valor</th><th scope="col">Referência</th></tr></thead><tbody><?php foreach($payments as$p):?><tr><td><?= e($date($p['data_pagamento'])) ?></td><td><?= e($money((int)$p['valor_centavos'])) ?></td><td><?= e($p['referencia']??'-') ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></article><article class="panel-card"><div class="panel-card-heading"><h2>Ajustes e estornos</h2></div><?php if(!$adjustments):?><div class="empty-preview affiliate-empty-compact"><div><strong>Nenhum ajuste registrado</strong><p>Estornos e compensações aparecerão aqui.</p></div></div><?php else:?><div class="responsive-table"><table class="panel-table affiliate-compact-table"><thead><tr><th scope="col">Data</th><th scope="col">Chácara</th><th scope="col">Valor</th><th scope="col">Movimentação</th></tr></thead><tbody><?php foreach($adjustments as$a):?><tr><td><?= e($date($a['criado_em'])) ?></td><td><?= e($a['chacara_nome']) ?></td><td class="affiliate-negative-value"><?= e($money((int)$a['valor_centavos'])) ?></td><td>Ajuste por estorno</td></tr><?php endforeach;?></tbody></table></div><?php endif;?></article></section>
